import './styles.css';
import { useState, useEffect, useRef } from 'react';
import { useStore } from './store/useStore';
import Toast from './components/Toast';
import AuthPage from './components/AuthPage';
import ChangePassword from './components/ChangePassword';

import AdminDashboard from './components/admin/AdminDashboard';
import CreateExam     from './components/admin/CreateExam';
import ManageExams    from './components/admin/ManageExams';
import StudentsPanel  from './components/admin/StudentsPanel';
import Analytics      from './components/admin/Analytics';
import Notifications  from './components/admin/Notifications';
import VivaRoom       from './components/admin/VivaRoom';

import StudentDashboard from './components/student/StudentDashboard';
import AvailableExams   from './components/student/AvailableExams';
import MyResults        from './components/student/MyResults';
import StudentProfile   from './components/student/StudentProfile';
import Leaderboard      from './components/student/Leaderboard';
import VivaJoin         from './components/student/VivaJoin';
import PracticeZone     from './components/student/PracticeZone';

const ADMIN_NAV = [
  { key:'dashboard',    label:'Dashboard',  icon:'▣' },
  { key:'exams',        label:'Exams',       icon:'📋' },
  { key:'create-exam',  label:'Create',      icon:'＋' },
  { key:'students',     label:'Students',    icon:'👥' },
  { key:'analytics',    label:'Analytics',   icon:'📊' },
  { key:'notifications',label:'Announce',    icon:'📢' },
  { key:'viva',         label:'Viva Room',   icon:'🎓' },
];
const STUDENT_NAV = [
  { key:'dashboard',       label:'Dashboard',       icon:'▣'  },
  { key:'available-exams', label:'Take Exam',        icon:'📝' },
  { key:'leaderboard',     label:'Leaderboard',      icon:'🏆' },
  { key:'my-results',      label:'My Results',       icon:'📄' },
  { key:'practice',        label:'Practice',         icon:'🧠' },
  { key:'notifications',   label:'Updates',          icon:'🔔' },
  { key:'viva-join',       label:'Viva',             icon:'🎓' },
];

export default function App() {
  const store = useStore();
  const [page,       setPage]       = useState('dashboard');
  const [examLocked, setExamLocked] = useState(false);
  const [showPwd,    setShowPwd]    = useState(false);
  const [userMenu,   setUserMenu]   = useState(false);
  const prevUserRef = useRef(null);
  const menuRef     = useRef();

  useEffect(() => {
    const uid = store.currentUser?.user_id || null;
    if (uid !== prevUserRef.current) {
      prevUserRef.current = uid;
      setPage('dashboard');
      setExamLocked(false);
    }
  }, [store.currentUser]);

  useEffect(() => {
    const h = (e) => { if (menuRef.current && !menuRef.current.contains(e.target)) setUserMenu(false); };
    document.addEventListener('mousedown', h);
    return () => document.removeEventListener('mousedown', h);
  }, []);

  // When exam is locked NOTHING can navigate — period
  const safePage = (p) => {
    if (examLocked) {
      store.addToast('⚠ You cannot navigate during an exam!', 'error');
      return;
    }
    setPage(p);
    setUserMenu(false);
  };

  const renderPage = () => {
    if (!store.currentUser) return null;
    const isAdmin = store.currentUser.role === 'admin';
    switch (page) {
      case 'dashboard':       return isAdmin ? <AdminDashboard store={store} setActivePage={safePage}/> : <StudentDashboard store={store} setActivePage={safePage}/>;
      case 'create-exam':     return <CreateExam    store={store}/>;
      case 'exams':           return <ManageExams   store={store}/>;
      case 'students':        return <StudentsPanel store={store}/>;
      case 'analytics':       return <Analytics     store={store}/>;
      case 'notifications':   return <Notifications store={store}/>;
      case 'available-exams': return <AvailableExams store={store} setExamLocked={setExamLocked}/>;
      case 'my-results':      return <MyResults     store={store}/>;
      case 'profile':         return <StudentProfile store={store}/>;
      case 'leaderboard':     return <Leaderboard   store={store}/>;
      case 'practice':        return <PracticeZone  store={store}/>;
      case 'viva':            return <VivaRoom       store={store} setActivePage={safePage}/>;
      case 'viva-join':       return <VivaJoin       store={store}/>;
      default:                return null;
    }
  };

  const user  = store.currentUser;
  const nav   = user?.role === 'admin' ? ADMIN_NAV : STUDENT_NAV;
  const init  = user?.name?.charAt(0).toUpperCase() || '?';
  const today = new Date().toLocaleDateString('en-US', { weekday:'short', month:'short', day:'numeric', year:'numeric' });

  return (
    <div className="app-root">
      {!user ? <AuthPage store={store}/> : (
        <>
          {/* ── TOPBAR ── */}
          <header style={{
            position:'fixed', top:0, left:0, right:0, height:52,
            background:'#fff', borderBottom:'1px solid #e8e8f0',
            display:'flex', alignItems:'center', padding:'0 20px',
            zIndex:200, gap:0, boxShadow:'0 1px 4px rgba(0,0,0,.06)',
          }}>
            {/* Logo — LOCKED during exam */}
            <div
              onClick={() => !examLocked && safePage('dashboard')}
              style={{ display:'flex', flexDirection:'column', paddingRight:20, borderRight:'1px solid #e8e8f0', marginRight:16, cursor:examLocked?'not-allowed':'pointer', flexShrink:0, gap:1, opacity:examLocked?0.4:1 }}>
              <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:18, color:'#0f0f1a', letterSpacing:-.5, lineHeight:1 }}>
                D<span style={{ color:'#7c3aed' }}>Exam</span>
              </div>
              <div style={{ fontSize:8, fontWeight:700, color:'#9ca3af', letterSpacing:2, textTransform:'uppercase', fontFamily:'JetBrains Mono,monospace' }}>
                EXAMINATION PLATFORM
              </div>
            </div>

            {/* Nav links — ALL LOCKED during exam */}
            <nav style={{ display:'flex', alignItems:'center', gap:1, flex:1 }}>
              {examLocked ? (
                // During exam: show lock bar instead of nav
                <div style={{ display:'flex', alignItems:'center', gap:8, background:'rgba(220,38,38,.06)', border:'1px solid rgba(220,38,38,.2)', borderRadius:8, padding:'5px 16px', flex:1, justifyContent:'center' }}>
                  <span style={{ fontSize:14 }}>🔒</span>
                  <span style={{ fontSize:12, fontWeight:700, color:'#dc2626', fontFamily:'JetBrains Mono,monospace', letterSpacing:.5 }}>
                    EXAM IN PROGRESS — Navigation locked until you submit
                  </span>
                </div>
              ) : (
                nav.map(item => (
                  <button key={item.key}
                    onClick={() => safePage(item.key)}
                    style={{
                      display:'flex', alignItems:'center', gap:6,
                      padding:'6px 14px', borderRadius:7, border:'1px solid transparent',
                      background: page===item.key ? '#f0eeff' : 'transparent',
                      color: page===item.key ? '#7c3aed' : '#6b7280',
                      fontWeight: page===item.key ? 700 : 500,
                      fontSize:13, cursor:'pointer', fontFamily:'Inter,sans-serif',
                      transition:'all .15s', whiteSpace:'nowrap', position:'relative',
                    }}>
                    <span style={{ fontSize:12 }}>{item.icon}</span>
                    {item.label}
                    {page===item.key && (
                      <span style={{ position:'absolute', bottom:-7, left:'50%', transform:'translateX(-50%)', width:'60%', height:2, background:'#7c3aed', borderRadius:2 }}/>
                    )}
                  </button>
                ))
              )}
            </nav>

            {/* Right side — LOCKED during exam */}
            <div style={{ display:'flex', alignItems:'center', gap:8, flexShrink:0, opacity:examLocked?0.35:1, pointerEvents:examLocked?'none':'auto' }}>
              {/* Date */}
              <div style={{ fontSize:12, color:'#7c3aed', fontFamily:'JetBrains Mono,monospace', background:'#f5f3ff', padding:'4px 10px', borderRadius:6, border:'1px solid #ede9fe', fontWeight:600 }}>
                {today}
              </div>
              {/* Bell */}
              <button onClick={() => safePage('notifications')}
                style={{ width:34, height:34, borderRadius:'50%', background:'#f9fafb', border:'1px solid #e5e7eb', display:'flex', alignItems:'center', justifyContent:'center', cursor:'pointer', fontSize:15 }}>
                🔔
              </button>
              {/* Profile icon */}
              {user.role === 'student' && (
                <button onClick={() => safePage('profile')} title="My Profile"
                  style={{ width:34, height:34, borderRadius:'50%', background:page==='profile'?'#ede9fe':'#f9fafb', border:`1px solid ${page==='profile'?'#7c3aed':'#e5e7eb'}`, display:'flex', alignItems:'center', justifyContent:'center', cursor:'pointer', fontSize:15 }}>
                  👤
                </button>
              )}
              {/* User dropdown */}
              <div ref={menuRef} style={{ position:'relative' }}>
                <div onClick={() => !examLocked && setUserMenu(m => !m)}
                  style={{ display:'flex', alignItems:'center', gap:8, padding:'4px 10px 4px 4px', borderRadius:8, border:'1px solid #e5e7eb', background:'#fff', cursor:examLocked?'not-allowed':'pointer' }}>
                  <div style={{ width:26, height:26, borderRadius:'50%', background:'linear-gradient(135deg,#7c3aed,#6d28d9)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:11, fontWeight:800, color:'white', overflow:'hidden', flexShrink:0 }}>
                    {user.avatar_url ? <img src={user.avatar_url} alt="" style={{width:'100%',height:'100%',objectFit:'cover'}}/> : init}
                  </div>
                  <div>
                    <div style={{ fontSize:12, fontWeight:700, color:'#0f0f1a', lineHeight:1 }}>{user.name.split(' ')[0]}</div>
                    <div style={{ fontSize:9, fontWeight:600, color:'#9ca3af', textTransform:'uppercase', letterSpacing:1, lineHeight:1.4 }}>{user.role}</div>
                  </div>
                  <span style={{ fontSize:9, color:'#9ca3af' }}>▾</span>
                </div>
                {userMenu && !examLocked && (
                  <div style={{ position:'absolute', top:'calc(100% + 6px)', right:0, background:'#fff', border:'1px solid #e5e7eb', borderRadius:12, padding:6, minWidth:180, boxShadow:'0 10px 32px rgba(0,0,0,.10)', zIndex:500 }} className="slide-down">
                    <div style={{ padding:'8px 12px 8px', borderBottom:'1px solid #f3f4f6', marginBottom:4 }}>
                      <div style={{ fontSize:13, fontWeight:700, color:'#0f0f1a' }}>{user.name}</div>
                      <div style={{ fontSize:11, color:'#9ca3af' }}>{user.email}</div>
                    </div>
                    {user.role==='student' && <DropItem icon="👤" label="My Profile" onClick={() => { safePage('profile'); setUserMenu(false); }}/>}
                    <DropItem icon="🔒" label="Change Password" onClick={() => { setShowPwd(true); setUserMenu(false); }}/>
                    <div style={{ height:1, background:'#f3f4f6', margin:'4px 0' }}/>
                    <div onClick={store.logout}
                      style={{ display:'flex', alignItems:'center', gap:9, padding:'8px 12px', borderRadius:8, cursor:'pointer', fontSize:13, color:'#dc2626', fontWeight:700 }}
                      onMouseEnter={e=>e.currentTarget.style.background='#fee2e2'}
                      onMouseLeave={e=>e.currentTarget.style.background='transparent'}>
                      ⏏ Sign Out
                    </div>
                  </div>
                )}
              </div>
            </div>
          </header>

          {/* Content */}
          <div style={{ marginTop:52, minHeight:'calc(100vh - 52px)', display:'flex', flexDirection:'column' }}>
            <div style={{ flex:1, padding:'28px 32px', maxWidth:1200, width:'100%', margin:'0 auto' }} className="fade-up">
              {renderPage()}
            </div>
            {/* Footer */}
            {!examLocked && (
              <div style={{ background:'#fff', borderTop:'1px solid #e8e8f0', padding:'14px 32px', display:'flex', alignItems:'center', justifyContent:'space-between', fontSize:12, color:'#9ca3af' }}>
                <div>© 2024 DExam Portal. Empowering education through technology.</div>
                <div style={{ display:'flex', gap:20 }}>
                  {['Help Center','Privacy Policy','Support'].map(l=>(
                    <span key={l} style={{ cursor:'pointer', color:'#9ca3af' }}
                      onMouseEnter={e=>e.currentTarget.style.color='#7c3aed'}
                      onMouseLeave={e=>e.currentTarget.style.color='#9ca3af'}>{l}</span>
                  ))}
                </div>
              </div>
            )}
          </div>
        </>
      )}
      {showPwd && !examLocked && <ChangePassword store={store} onClose={() => setShowPwd(false)}/>}
      <Toast toasts={store.toasts}/>
    </div>
  );
}

function DropItem({ icon, label, onClick }) {
  const [hov, setHov] = useState(false);
  return (
    <div onClick={onClick} onMouseEnter={()=>setHov(true)} onMouseLeave={()=>setHov(false)}
      style={{ display:'flex', alignItems:'center', gap:9, padding:'8px 12px', borderRadius:8, cursor:'pointer', fontSize:13, color:'#374151', fontWeight:600, background:hov?'#f9fafb':'transparent' }}>
      <span style={{fontSize:14}}>{icon}</span> {label}
    </div>
  );
}
